import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { loadDefaultGameData } from '../src/data/node';
import { StatsError } from '../src/errors';
import { defaultIvFloor, rankIvs, type IvRankEntry } from '../src/stats/ivRank';
import type { IvCombinationsRequest } from '../scripts/oracle/harness';

const gd = loadDefaultGameData();
const sp = (id: string) => gd.species.get(id)!;

interface IvCase { request: IvCombinationsRequest; chargedMoveIds: string[]; combinations: string }
// Generated by `npm run gen-iv-oracle` from PvPoke's Pokemon.generateIVCombinations('overall', 1, 4096).
const fixture: { upstream: string; cases: IvCase[] } = JSON.parse(readFileSync('tests/fixtures/iv-rank-oracle.json', 'utf8'));
const encode = (r: IvRankEntry): string => `${r.ivs.atk.toString(16)}${r.ivs.def.toString(16)}${r.ivs.hp.toString(16)}${r.level}`;

describe('rankIvs matches PvPoke IV ranks', () => {
  it('fixture was generated from the vendored PvPoke commit', () => {
    expect(fixture.upstream).toBe(readFileSync('data/UPSTREAM', 'utf8').trim());
    expect(fixture.cases.length).toBeGreaterThanOrEqual(25);
  });

  for (const c of fixture.cases) {
    const { speciesId, cap, ivFloor } = c.request;
    it(`${speciesId} cap ${cap}${ivFloor === undefined ? '' : ` ivFloor ${ivFloor}`} [${c.chargedMoveIds.join(', ')}]: full order and levels`, () => {
      const opts = { cap, chargedMoveIds: c.chargedMoveIds, ...(ivFloor === undefined ? {} : { ivFloor }) };
      if (c.combinations === '') {
        expect(() => rankIvs(sp(speciesId), opts)).toThrow(StatsError);
        return;
      }
      expect(rankIvs(sp(speciesId), opts).map(encode).join(' ')).toBe(c.combinations);
    });
  }

  it('PvPoke ranks Medicham 5/15/15 first (14 hp loses the float tie-break)', () => {
    expect(rankIvs(sp('medicham'))[0]!.ivs).toEqual({ atk: 5, def: 15, hp: 15 });
  });
});

describe('rankIvs', () => {
  const ranks = rankIvs(sp('medicham'));

  it('covers all 4096 combinations for a species that fits the cap', () => {
    expect(ranks).toHaveLength(4096);
  });

  it('sorts by stat product descending with 1-based ranks', () => {
    expect(ranks[0]!.rank).toBe(1);
    for (let i = 1; i < ranks.length; i++) {
      expect(ranks[i - 1]!.statProduct).toBeGreaterThanOrEqual(ranks[i]!.statProduct);
    }
    expect(ranks[0]!.percentOfBest).toBe(100);
  });

  it('never exceeds the cap', () => {
    expect(ranks.every((r) => r.cp <= 1500)).toBe(true);
  });

  it('respects the IV floor', () => {
    const lucky = rankIvs(sp('medicham'), { ivFloor: 12 });
    expect(lucky).toHaveLength(64);
    expect(lucky.every((r) => r.ivs.atk >= 12 && r.ivs.def >= 12 && r.ivs.hp >= 12)).toBe(true);
  });

  it('lets an explicit ivFloor override the species default', () => {
    expect(rankIvs(sp('registeel'), { ivFloor: 0 })).toHaveLength(4096);
  });

  it('never ranks a level below the species levelFloor', () => {
    expect(sp('giratina_origin').levelFloor).toBe(15);
    expect(rankIvs(sp('giratina_origin')).every((r) => r.level >= 15)).toBe(true);
  });

  it('throws StatsError when no combination fits under the cap', () => {
    expect(() => rankIvs(sp('darkrai'))).toThrow(StatsError);
    expect(() => rankIvs(sp('mewtwo'), { cap: 10 })).toThrow(StatsError);
  });

  it('matches the stat product PvPoke publishes for its default Melmetal', () => {
    const entry = rankIvs(sp('melmetal')).find((r) => r.ivs.atk === 4 && r.ivs.def === 10 && r.ivs.hp === 14)!;
    // rankings-1500.json lists stats.product 1858 (= atk*def*hp / 1000, rounded)
    expect(Math.round(entry.statProduct / 1000)).toBe(1858);
  });
});

describe('defaultIvFloor (PvPoke generateIVCombinations floor rules)', () => {
  it.each([
    ['medicham', [], 0], ['registeel', [], 1], ['raikou', [], 0], ['zapdos_shadow', [], 6],
    ['raikou_shadow', [], 6], ['jirachi', [], 10], ['ivysaur', ['POWER_WHIP', 'RETURN'], 2],
  ] as [string, string[], number][])('%s %j -> %i', (id, moves, floor) => {
    expect(defaultIvFloor(sp(id), moves)).toBe(floor);
  });
});
